// ─── LOGIN ───────────────────────────────────────────────────────────────────
function login(){
  var u = $("username").value;
  var p = $("password").value;
  loginBtn.disabled = true;
  loginBtn.textContent = "Connecting...";

  fetchTimeout(API_URL + "/auth/login", {
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({username:u, password:p})
  })
  .then(function(res){
    return res.json().then(function(data){ return {status:res.status, data:data}; });
  })
  .then(function(r){
    if(r.status === 200 || r.status === 201){
      AUTH_TOKEN = r.data.accessToken || r.data.access_token || r.data.token;
      REFRESH_TOKEN = r.data.refreshToken || r.data.refresh_token;
      localStorage.setItem("@scanner_refresh", REFRESH_TOKEN);
      setConnected("CONNECTED", "#4cd964");
      log("Login successful.", "success");
      fetchData();
    } else {
      log("Login error " + r.status + ": " + (r.data.message || r.data.code || "Invalid credentials"), "error");
      loginBtn.disabled = false;
      loginBtn.textContent = "Connect to Backend";
      return; // don't proceed to show scanner
    }
    showScanner();
  })
  .catch(function(){
    AUTH_TOKEN = "offline-demo-token";
    setConnected("OFFLINE MODE", "#ff9500");
    log("Backend unreachable — offline demo mode active.", "info");
    showScanner();
  });
}

function setConnected(label, color){
  statusBadge.textContent = label;
  statusBadge.style.color = color;
}

function restoreSessionFromRefreshToken(){
  if(!REFRESH_TOKEN || REFRESH_TOKEN === "offline-demo-token") return;

  setConnected("RESTORING...", "#ff9500");
  fetchTimeout(API_URL + "/auth/refresh", {
    method: "POST",
    headers: { "Content-Type": "text/plain" },
    body: REFRESH_TOKEN
  })
  .then(function(res){
    if(res.status !== 201) throw new Error("refresh failed (" + res.status + ")");
    return res.json();
  })
  .then(function(data){
    AUTH_TOKEN = data.accessToken || data.token;
    REFRESH_TOKEN = data.refreshToken || REFRESH_TOKEN;
    localStorage.setItem("@scanner_refresh", REFRESH_TOKEN);
    setConnected("CONNECTED", "#4cd964");
    log("Session restored.", "success");
    showScanner();
  })
  .catch(function(){
    setConnected("DISCONNECTED", "#666");
  });
}

