// ─── CAMERA ──────────────────────────────────────────────────────────────────
function toggleCamera(){
  if(!qrLibLoaded || !readBarcodesFn){ log("QR library not ready yet.", "error"); return; }
  if(cameraOn){
    stopCamera();
  } else {
    startCamera();
  }
}

function startCamera(){
  ensureScanElements();
  normalizeCameraViewport();
  likelyQrStreak = 0;
  hideScanHint();
  resetAdaptiveCameraState();

  if(!(navigator && navigator.mediaDevices && navigator.mediaDevices.getUserMedia)){
    log("Camera API unavailable. Open this page over https:// or localhost (not plain file://).", "error");
    return;
  }

  if(window.isSecureContext === false){
    log("Insecure page context. Camera requires https:// or localhost.", "error");
    return;
  }

  navigator.mediaDevices.getUserMedia({
    video: { facingMode: "environment" },
    audio: false
  })
  .then(function(stream){
    cameraStream = stream;
    cameraTrack = stream.getVideoTracks && stream.getVideoTracks()[0] ? stream.getVideoTracks()[0] : null;

    if(cameraTrack && typeof cameraTrack.getCapabilities === "function"){
      try{
        var caps = cameraTrack.getCapabilities() || {};
        if(caps.zoom){
          zoomCap = caps.zoom;
          zoomMin = Number(caps.zoom.min || 1);
          zoomMax = Number(caps.zoom.max || 1);
          zoomStep = Number(caps.zoom.step || 0.1) || 0.1;
          currentZoom = Number((cameraTrack.getSettings && cameraTrack.getSettings().zoom) || zoomMin);
          targetZoom = zoomMin;
          maybeUpdateHardwareZoom();
        }
        if(caps.focusMode && cameraTrack.applyConstraints){
          cameraTrack.applyConstraints({ advanced: [{ focusMode: "continuous" }] }).catch(function(){});
        }
      } catch(_e){
        // Some browsers throw when probing capabilities.
      }
    }

    scanVideoEl.srcObject = stream;
    camHolder.style.display = "none";
    cameraOn = true;
    camBtn.textContent = "Stop Camera";
    camBtn.classList.add("secondary");
    processingFlag = false;
    scanOverlay.classList.add("hidden");
    hideScanHint();
    if(scanLoopId) cancelAnimationFrame(scanLoopId);
    scanLoopId = requestAnimationFrame(scanFrameLoop);
    log("Camera started.", "success");
  })
  .catch(function(err){
    var msg = err && err.message ? err.message : "Unknown camera error";
    if(err && err.name === "NotAllowedError"){
      msg = "Camera permission denied. Allow camera access in browser site settings.";
    } else if(err && err.name === "NotFoundError"){
      msg = "No camera device found.";
    } else if(err && err.name === "NotReadableError"){
      msg = "Camera is busy (in use by another app).";
    }
    log("Camera error: " + msg, "error");
    stopCamera();
  });
}

function stopCamera(){
  if(scanLoopId){
    cancelAnimationFrame(scanLoopId);
    scanLoopId = null;
  }
  if(cameraStream){
    cameraStream.getTracks().forEach(function(t){ t.stop(); });
    cameraStream = null;
  }
  if(scanVideoEl) scanVideoEl.srcObject = null;
  cameraOn = false;
  camBtn.textContent = "Start Camera";
  camBtn.classList.remove("secondary");
  camHolder.style.display = "";
  isDecodingFrame = false;
  likelyQrStreak = 0;
  hideScanHint();
  resetAdaptiveCameraState();
}

function scanFrameLoop(ts){
  if(!cameraOn || !scanVideoEl || !scanCanvasEl){
    scanLoopId = null;
    return;
  }

  if(processingFlag || isDecodingFrame || scanVideoEl.readyState < 2 || (ts - lastDecodeTs) < SCAN_INTERVAL_MS){
    updateDigitalZoomVisualSmooth();
    scanLoopId = requestAnimationFrame(scanFrameLoop);
    return;
  }

  lastDecodeTs = ts;
  isDecodingFrame = true;

  var w = scanVideoEl.videoWidth || 0;
  var h = scanVideoEl.videoHeight || 0;
  if(!w || !h){
    isDecodingFrame = false;
    updateDigitalZoomVisualSmooth();
    scanLoopId = requestAnimationFrame(scanFrameLoop);
    return;
  }

  if(scanCanvasEl.width !== w) scanCanvasEl.width = w;
  if(scanCanvasEl.height !== h) scanCanvasEl.height = h;
  var ctx = scanCanvasEl.getContext("2d", { willReadFrequently: true });
  if(!ctx){
    isDecodingFrame = false;
    updateDigitalZoomVisualSmooth();
    scanLoopId = requestAnimationFrame(scanFrameLoop);
    return;
  }

  ctx.drawImage(scanVideoEl, 0, 0, w, h);
  var frame = ctx.getImageData(0, 0, w, h);

  readBarcodesFn(frame, { formats: ["QRCode"], maxNumberOfSymbols: 1, tryHarder: true })
    .then(function(results){
      if(results && results.length > 0 && results[0].text){
        likelyQrStreak = 0;
        hideScanHint();
        resetDigitalZoomVisual();
        targetZoom = zoomMin;
        maybeUpdateHardwareZoom();
        onScanSuccess(results[0].text);
        return;
      }

      if(!advancedScanEnabled){
        likelyQrStreak = 0;
        hideScanHint();
        visualTargetZoom = 1;
        if(zoomCap){
          targetZoom = zoomMin;
          maybeUpdateHardwareZoom();
        }
        return;
      }

      var likely = detectLikelyQrPresence(frame, w, h);
      if(likely) likelyQrStreak = Math.min(likelyQrStreak + 1, 5);
      else likelyQrStreak = Math.max(0, likelyQrStreak - 1);

      var now = Date.now();
      if(likelyQrStreak >= 2 && (now - lastHintTs) > 1800 && !processingFlag){
        showScanHint("Possible QR seen. Move closer and hold steady.");
        lastHintTs = now;
      }

       adaptScannerWhenLikelyQr();

       if(likelyQrStreak >= 1 && !processingFlag){
         return runSmartDecodeSweep(frame, w, h).then(function(foundText){
           if(foundText){
             likelyQrStreak = 0;
             hideScanHint();
             resetDigitalZoomVisual();
             targetZoom = zoomMin;
             maybeUpdateHardwareZoom();
             onScanSuccess(foundText);
           }
         });
       }

       if(likelyQrStreak === 0 && zoomCap){
         targetZoom = zoomMin;
         maybeUpdateHardwareZoom();
       }
    })
    .catch(function(){
      // Ignore per-frame decode misses/errors to keep scanner smooth.
    })
    .finally(function(){
      updateDigitalZoomVisualSmooth();
      isDecodingFrame = false;
      if(cameraOn) scanLoopId = requestAnimationFrame(scanFrameLoop);
    });
}

function onScanSuccess(txt){
  if(processingFlag) return;
  processingFlag = true;
  log("QR detected! Processing...", "info");
  handleRawQR(txt);
}

function resetScanner(){
  scanOverlay.classList.add("hidden");
  hideScanHint();
  resetDigitalZoomVisual();
  processingFlag = false;
  if(cameraOn && !scanLoopId) scanLoopId = requestAnimationFrame(scanFrameLoop);
  log("Ready for next tablet.", "info");
}

