// ─── QR DATA PROCESSING ──────────────────────────────────────────────────────

function fetchWithAuth(url, options) {
  if (!options) options = {};
  if (!options.headers) options.headers = {};
  options.headers["Authorization"] = "Bearer " + AUTH_TOKEN;

  return fetchTimeout(url, options).then(function(res) {
    if (res.status === 401 && REFRESH_TOKEN && REFRESH_TOKEN !== "offline-demo-token") {
      return fetchTimeout(API_URL + "/auth/refresh", {
        method: "POST",
        headers: { "Content-Type": "text/plain" },
        body: REFRESH_TOKEN
      }).then(function(refreshRes) {
        if (refreshRes.status === 201) {
          return refreshRes.json().then(function(data) {
            AUTH_TOKEN = data.accessToken || data.token;
            REFRESH_TOKEN = data.refreshToken;
            localStorage.setItem("@scanner_refresh", REFRESH_TOKEN);
            options.headers["Authorization"] = "Bearer " + AUTH_TOKEN;
            return fetchTimeout(url, options); // Retry with new token
          });
        } else {
          return res; // Pass through 401 if refresh failed
        }
      }).catch(function() { return res; });
    }
    return res;
  });
}

function handleRawQR(raw){
  var chunks = raw.split("#").filter(function(s){ return s.trim().length > 0; });
  var accepted = [];
  var batchSeen = Object.create(null);

  chunks.forEach(function(chunk){
    var normalized = chunk.trim();
    var key = buildScanKey(normalized);
    if(batchSeen[key]){
      log("Duplicate code in same scan payload ignored (" + key + ").", "info");
      return;
    }
    batchSeen[key] = true;

    if(scanSavedKeys[key]){
      log("Duplicate scan blocked (already saved this session): " + key, "error");
      return;
    }
    if(scanInFlightKeys[key]){
      log("Duplicate scan blocked (already processing): " + key, "info");
      return;
    }

    scanInFlightKeys[key] = true;
    accepted.push({ chunk: normalized, key: key });
  });

  if(accepted.length === 0){
    log("No new match data to process from this scan.", "info");
    processingFlag = false;
    if(cameraOn && !scanLoopId) scanLoopId = requestAnimationFrame(scanFrameLoop);
    return;
  }

  var chain  = Promise.resolve(null);
  var last   = null;
  accepted.forEach(function(item){
    chain = chain
      .then(function(){ 
        // Intercept PIT Scouting reports directly
        if (item.chunk.startsWith("PIT|")) {
          return processPitReport(item.chunk);
        }
        return processSingleMatch(item.chunk); 
      })
      .then(function(r){
        delete scanInFlightKeys[item.key];
        if(r){
          scanSavedKeys[item.key] = true;
          last = r;
        }
      })
      .catch(function(){
        delete scanInFlightKeys[item.key];
      });
  });
  chain.then(function(){
    if(last){ showSuccess(last.match, last.team); fetchData(); }
    else {
      processingFlag = false;
      if(cameraOn && !scanLoopId) scanLoopId = requestAnimationFrame(scanFrameLoop);
    }
  });
}

function processPitReport(str) {
  var p = str.split("|");
  var pitData = {
    teamNumber: p[1] || "Unknown",
    drivetrain: p[2] || "",
    shooter: p[3] || "",
    hasDrumShooter: p[4] === "1",
    estimatedBps: p[5] || "",
    driverExperience: p[6] || "",
    weight: p[7] || "",
    width: p[8] || "",
    length: p[9] || "",
    autoRoutines: p[10] || "",
    canFerry: p[11] === "1",
    canClimb: p[12] === "1",
    climbLevels: p[13] ? p[13].split(',').map(Number) : [],
    notes: p[14] || "",
    createdAt: new Date().toISOString()
  };

  var existing = JSON.parse(localStorage.getItem("@scanner_pit_reports") || "[]");
  // Overwrite existing data for the same team
  existing = existing.filter(function(r) { return r.teamNumber !== pitData.teamNumber; });
  existing.push(pitData);
  localStorage.setItem("@scanner_pit_reports", JSON.stringify(existing));

  log("Saved local Pit Report for Team " + pitData.teamNumber, "success");
  return Promise.resolve({ match: "PIT", team: pitData.teamNumber });
}

function printAllPitReports() {
  var reports = JSON.parse(localStorage.getItem("@scanner_pit_reports") || "[]");
  if(reports.length === 0) { alert("No Pit Reports scanned yet."); return; }

  var rows = reports.map(function(r) {
