  }).join("");

  var html = "<h1>Scanned Pit Reports (Offline Cache)</h1>" +
    "<p>These reports were scanned via QR Code directly from devices.</p>" +
    "<table border='1' cellspacing='0' cellpadding='8' style='width:100%; text-align:left; border-collapse:collapse;'>" +
    "<tr style='background:#f0f0f0'><th>Team</th><th>Drive</th><th>Shooter</th><th>Drum?</th><th>Est. BPS</th><th>Exp</th><th>Weight</th><th>Auto</th><th>Notes</th></tr>" +
    rows + "</table>";

  openPrint(html, "");
}

function processSingleMatch(str){
  var p = str.split("|");
  if(p.length < 3){
    log("Invalid format (len " + p.length + ").", "error");
    return Promise.resolve(null);
  }

  var matchNum = parseInt(p[1], 10);
  var teamNum = parseInt(p[2], 10);
  if(isNaN(matchNum) || isNaN(teamNum)){
    log("Invalid match/team values in QR payload.", "error");
    return Promise.resolve(null);
  }

  // Support old schema vs new schema (indexes 18 & 19 contain pure auto and teleop notes respectively)
  var payloadNotes = p[17] || "";
  var autoNotes = p[18] || "";
  var teleNotes = p[19] || "";

  var extra =
    "[Start:" +
    (p[4] || "CENTER") +
    "] [Pass:" +
    (p[8] || "None") +
    "] [AutoWin:" +
    (p[9] || "Tie") +
    "] [Ferry:" +
    (p[11] || 0) +
    "] [Bump:" +
    (p[12] || "false").toString() +
    "] [Trench:" +
    (p[13] || "false").toString() +
    "] [Defended:" +
    (p[20] || "false").toString() +
    "] [Time:" +
    (p[15] || "0") +
    "s] [Dead:" +
    (p[16] || "OK") +
    "]";

  var rawNotes = payloadNotes ? payloadNotes : extra + " | ";

  var deadFromFlag = (p[16] === "DIE") ? 150 : 0;
  var deadFromNotes = 0;
  var deadMatch = rawNotes.match(/(?:\[DeadTime:|dT:)(\d+)/i);
  if(deadMatch && deadMatch[1]) deadFromNotes = parseInt(deadMatch[1], 10) || 0;
  var incapSeconds = deadFromNotes || deadFromFlag;

  var payload = {
    createdAt: new Date().toISOString(),
    eventCode: (p[0] || "pncmp").substring(0,5).padEnd(5,"A"),
    matchType: "QUALIFICATION",
    matchNumber: matchNum,
    alliance: p[21] ? (p[21].startsWith('Blue') ? 'BLUE' : 'RED') : 'RED',
    teamNumber:  teamNum,
    inMatch: true,
    notes: rawNotes.substring(0,400),
    minorFouls: parseInt(p[22], 10) || 0,
    majorFouls: 0,
    secondsIncapacitated: incapSeconds,
    secondsDead: incapSeconds,
    shootingConfidence: 3,
    auto:{
      notes: autoNotes.substring(0,400),
      hubScores: parseInt(p[5],10)||0, hubMisses: parseInt(p[6],10)||0,
      climb: p[7]==="Yes"?"LEVEL1":(p[7]==="Fail"?"FAILED":"NONE"),
      passes: p[8]==="High"?3:(p[8]==="Med"?2:(p[8]==="Low"?1:0))
    },
    teleop:{
      notes: teleNotes.substring(0,400),
      hubScores: parseInt(p[10],10)||0, hubMisses:0, level:0,
      climbFailed:false, defended: p[20]==="true" || p[20]==="1", passes: parseInt(p[11],10)||0,
      wasDefended: false
    },
    endgame:{
      notes:"",
      level: p[14]==="Level 3"?3:(p[14]==="Level 2"?2:(p[14]==="Level 1"?1:0)),
      climbFailed: p[14]==="Failed"
    }
  };

  return fetchWithAuth(API_URL + "/report", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)
  })
  .then(function(res){
    if(res.status === 201){
      log("Saved Match " + p[1] + " (Team " + p[2] + ")", "success");
      upsertRecentReport(payload, "Saved");
      checkUpcomingPrint(parseInt(p[1], 10));
      return {match:p[1], team:p[2]};
    }
    return res.json().then(function(err){
      if(err.message && err.message.indexOf("Unique") !== -1){
        log("Match " + p[1] + " already saved. Skipped.", "info");
        upsertRecentReport(payload, "Saved");
        checkUpcomingPrint(parseInt(p[1], 10));
        return {match:p[1], team:p[2]};
      }
      log("Backend rejected Match " + p[1] + " (Team " + p[2] + "): " + (err.message || JSON.stringify(err)), "error");
      var queued = enqueuePendingReport(payload);
      if(queued){
        log("Offline save queued for Match " + p[1] + " (Team " + p[2] + ").", "info");
        upsertRecentReport(payload, "Queued");
      }
      checkUpcomingPrint(parseInt(p[1], 10));
      return {match:p[1], team:p[2]};
    });
  })
  .catch(function(_e){
    var queued = enqueuePendingReport(payload);
    if(queued){
      log("Offline save queued for Match " + p[1] + " (Team " + p[2] + ").", "info");
      upsertRecentReport(payload, "Queued");
    }
    else { log("Already queued offline: Match " + p[1] + " (Team " + p[2] + ").", "info"); }
    checkUpcomingPrint(parseInt(p[1], 10));
    return {match:p[1], team:p[2]};
  });
}

